#define ANARI_EXTENSION_UTILITY_IMPL
#include <anari/anari_cpp.hpp>
#include <anari/ext/visrtx/makeVisRTXDevice.h>
#include <cstdio>
#include <string>
#include <thread>
#include <vector>

static void commitSelected(anari::Device d, const char *sel)
{
  auto mat = anari::newObject<anari::Material>(d, "materialx");
  anari::setParameter(d, mat, "source",
      std::string(MATERIALX_TEST_DATA_DIR) + "/two_materials.mtlx");
  anari::setParameter(d, mat, "materialName", std::string(sel));
  anari::commitParameters(d, mat);
  anari::release(d, mat);
}

int main()
{
  auto d = anari::Device(makeVisRTXDevice());

  // Selection: both names commit without error.
  commitSelected(d, "Mat_Red");
  commitSelected(d, "Mat_Blue");

  // Concurrency: many materialx materials committed from several threads.
  // No mutex is needed: anariCommitParameters only QUEUES the object; the
  // actual transcode and MDL compile run inside helium's DeferredCommitBuffer::
  // flush(), which is single-threaded under m_flushMutex — concurrent
  // transcode/compile is structurally precluded by the harness.
  std::vector<std::thread> threads;
  for (int t = 0; t < 8; ++t)
    threads.emplace_back([d, t] {
      commitSelected(d, (t % 2) ? "Mat_Red" : "Mat_Blue");
    });
  for (auto &th : threads)
    th.join();

  anari::release(d, d);
  std::printf("PASS\n");
  return 0;
}

